def provider_x0(map_path, *, edge: dict, cond_id: str, lb, ub, parameter_order: list) -> tuple:
    """봉인된 solution map 에서 **이 조건·이 objective** 의 좌표를 꺼내 실제 x0 로 만든다 (표 C 소비 규칙).

    거부: 파일 sha ≠ edge(봉인 전 소비 · 다른 map) · header 의 objective/artifact/protocol/order ≠ edge ·
    cond_id 부재(**no-warm 으로 바꾸지 않는다**) · 비유한 · 길이 불일치 · **bounds 밖(clip 없음)**.
    반환 `(x0, x0_sha256)` — 이 digest 가 후보 map 에 기록돼 solver 입력과 결속된다.
    """
    from tools.design_wire import x0_sha256
    raw = Path(map_path).read_bytes()
    got = hashlib.sha256(raw).hexdigest()
    if got != edge.get("solution_map_sha256"):
        raise ValueError(f"solution map 바이트 sha {got[:16]} ≠ edge 의 solution_map_sha256 "
                         f"{str(edge.get('solution_map_sha256'))[:16]} — 봉인 전 소비이거나 다른 map 이다")
    doc = json.loads(raw.decode("utf-8"))
    hdr = doc.get("header") or {}
    if hdr.get("schema") != _SOLUTION_MAP_SCHEMA:
        raise ValueError(f"solution map schema: {hdr.get('schema')!r}")
    for hk, ek in (("provider_objective", "provider_objective"),
                   ("provider_artifact_sha256", "provider_artifact_sha256"),
                   ("provider_protocol_sha256", "provider_protocol_sha256")):
        if hdr.get(hk) != edge.get(ek):
            raise ValueError(f"solution map header 의 {hk} ({str(hdr.get(hk))[:16]}) ≠ edge 의 {ek} "
                             f"({str(edge.get(ek))[:16]}) — 다른 fits/objective/protocol 의 map 이다")
    if hdr.get("parameter_order") != list(parameter_order):
        raise ValueError(f"solution map parameter_order {hdr.get('parameter_order')!r} ≠ {list(parameter_order)!r}")
    entry = (doc.get("entries") or {}).get(cond_id)
    if entry is None:
        raise ValueError(f"solution map 에 cond_id {cond_id!r} 가 없다 — warm 이 필요한 자리의 누락은 오류이지 no-warm 이 아니다"
                         + (f" (제외 목록에 있음: 비유한 provider 해)" if cond_id in (hdr.get("excluded_cond_ids") or []) else ""))
    p = np.asarray([float(v) for v in entry["p"]], float)
    lb = np.asarray(lb, float); ub = np.asarray(ub, float)
    if p.shape != lb.shape or not np.isfinite(p).all():
        raise ValueError(f"provider 좌표 길이/유한성 위반: {p.tolist()}")
    if (p < lb).any() or (p > ub).any():
        raise ValueError(f"provider 좌표가 bounds 밖이다 — clip 하지 않고 거부한다: {p.tolist()}")
    return p, x0_sha256(p)

def canonical_bytes(obj) -> bytes:
    """정규 직렬화. 키 정렬 · UTF-8 · 구분자 고정 · 후행 개행 없음."""
    return json.dumps(obj, sort_keys=True, ensure_ascii=False,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def load_canonical(raw: bytes):
    """`canonical_bytes` 의 역. 회수한 object 를 되돌린다."""
    return json.loads(raw.decode("utf-8"))


def digest(obj) -> str:
    return hashlib.sha256(canonical_bytes(obj)).hexdigest()

def check_execution_record(rec, planned_env) -> list[str]:
    """`execution-record/v1` (실현 기록) 을 그 계획과 대조한다 (★ 81차 G81-N1).

    계획은 바뀌지 않는다: record 는 `planned_id` 로 계획을 **참조**하고, 실현 count 는 계획 count 와
    같은 자료가 아니라 계획 **아래** 있어야 한다 (attempted = returned + failed · attempted + not_attempted =
    계획 총합 · source 별 ≤ 계획 · prefix ≤ bank.length). 예상 count 를 실제로 복사해 채운 record 도
    정상 record 와 구별되지 않지만, 그것은 writer 의 시험(candidate map sha)이 잡는다.
    """
    if not isinstance(rec, dict):
        return [f"execution record 가 dict 가 아니다: {type(rec).__name__}"]
    if set(rec) != _RECORD_KEYS:
        return [f"execution record 키 집합이 닫혀 있지 않다: {sorted(set(rec) ^ _RECORD_KEYS)}"]
    bad = []
    # ★ 84차 G84-N4 — schema 로 분기 (v1 · v2). 모르는 schema 는 여기서 끝.
    _obj_keys = _RECORD_SCHEMA_KEYS.get(rec["schema"])
    if _obj_keys is None:
        return [f"schema: {rec['schema']!r} (지원 {sorted(_RECORD_SCHEMA_KEYS)})"]
    if rec["record_digest"] != digest({k: v for k, v in rec.items() if k != "record_digest"}):
        bad.append("record_digest 가 자기 내용과 다르다")
    envbad = check_planned_envelope(planned_env)
    if envbad or planned_env.get("schema") != "planned-leg/v4":
        return bad + ["대조할 계획이 유효한 planned-leg/v4 가 아니다: " + "; ".join(envbad[:2])]
    if rec["leg_id"] != planned_env["leg_id"]:
        bad.append("leg_id 가 계획과 다르다")
    if rec["planned_id"] != digest(planned_env):
        bad.append(f"planned_id {str(rec['planned_id'])[:16]!r} 가 이 계획의 digest 가 아니다 — 다른 계획의 기록")
    if rec["source_digest"] != planned_env["source_digest"]:
        bad.append("source_digest 가 계획과 다르다 (code identity)")
    if rec["protocol_generation"] != planned_env["protocol_generation"]:
        bad.append("protocol_generation 이 계획과 다르다")
    rz = rec["realized"]
    if not isinstance(rz, dict) or set(rz) != _REALIZED_KEYS:
        return bad + [f"realized 키 집합이 닫혀 있지 않다: {sorted(rz) if isinstance(rz, dict) else rz!r}"]
    pc = planned_env["planned_counts"]
    bo = rz["by_objective"]
    if not isinstance(bo, dict) or set(bo) != set(planned_env["objective_order"]):
        bad.append("realized.by_objective 의 objective 집합이 계획과 다르다")
    else:
        for obj, r in bo.items():
            if not isinstance(r, dict) or set(r) != _obj_keys:
                bad.append(f"{obj}: realized 항목 키가 {rec['schema']} 의 닫힌 집합이 아니다")
                continue
            ints = {k: r[k] for k in ("attempted", "returned", "failed", "not_attempted", "random_bank_prefix_len")}
            if not all(_nonneg_int(v) for v in ints.values()):
                bad.append(f"{obj}: 실현 count 가 음이 아닌 정수가 아니다: {ints!r}")
                continue
            if "finite" in _obj_keys:
                # ★ 84차 G84-N4 — `0 ≤ finite, converged ≤ returned` · 둘 사이 포함 관계는 가정하지 않는다 ·
                #   누락/타입 오류를 0/False 로 바꾸지 않는다 (닫힌 키 검사가 누락을, 여기가 타입·범위를 잡는다)
                for k in ("finite", "converged"):
                    if not _nonneg_int(r[k]) or r[k] > r["returned"]:
                        bad.append(f"{obj}: {k} {r[k]!r} 가 0..returned({r['returned']}) 의 정수가 아니다")
            if r["attempted"] != r["returned"] + r["failed"]:
                bad.append(f"{obj}: attempted {r['attempted']} ≠ returned {r['returned']} + failed {r['failed']}")
            # 계획 count 는 **조건 하나**의 후보 구성이고 실현 count 는 다리 전체(조건 × 후보)의 합이다 —
            #   계획 총합 = 조건당 계획 × roster n_obs (계획 roster 가 조건 집합의 사전 크기다)
            n_obs = planned_env["roster"]["n_obs"]
            planned_total = sum(pc[obj].values()) * n_obs
            if r["attempted"] + r["not_attempted"] != planned_total:
                bad.append(f"{obj}: attempted + not_attempted = {r['attempted'] + r['not_attempted']} ≠ 계획 총합 {planned_total} (조건당 {sum(pc[obj].values())} × roster {n_obs})")
